<?php
if ($user['role'] === 'Admin') {
    $payments = db()->query("SELECT p.*, u.name, r.roomNumber, i.billMonth, f.description AS fineDescription
        FROM Payment p
        JOIN Contract c ON c.contractId = p.contractId
        JOIN `User` u ON u.userId = c.userId
        JOIN Room r ON r.roomId = c.roomId
        LEFT JOIN Invoice i ON i.invoiceId = p.invoiceId
        LEFT JOIN Fine f ON f.fineId = p.fineId
        ORDER BY p.paymentDate DESC")->fetchAll();
    $activeContracts = db()->query("SELECT c.contractId, u.name, r.roomNumber FROM Contract c JOIN `User` u ON u.userId = c.userId JOIN Room r ON r.roomId = c.roomId WHERE c.status = 'ใช้งานอยู่' ORDER BY r.roomNumber")->fetchAll();
    $invoices = db()->query("SELECT i.*, u.name, r.roomNumber,
        i.rentAmount + (i.waterUnit * i.waterRate) + (i.electricUnit * i.electricRate) AS total
        FROM Invoice i JOIN Contract c ON c.contractId = i.contractId
        JOIN `User` u ON u.userId = c.userId JOIN Room r ON r.roomId = c.roomId
        ORDER BY i.dueDate DESC, r.roomNumber")->fetchAll();
    $fines = db()->query("SELECT f.*, u.name, r.roomNumber
        FROM Fine f JOIN Contract c ON c.contractId = f.contractId
        JOIN `User` u ON u.userId = c.userId JOIN Room r ON r.roomId = c.roomId
        ORDER BY f.fineDate DESC, r.roomNumber")->fetchAll();
} else {
    $statement = db()->prepare("SELECT p.*, r.roomNumber FROM Payment p JOIN Contract c ON c.contractId = p.contractId JOIN Room r ON r.roomId = c.roomId WHERE c.userId = ? ORDER BY p.paymentDate DESC");
    $statement->execute([$user['userId']]);
    $payments = $statement->fetchAll();
    $statement = db()->prepare("SELECT i.*, r.roomNumber, i.rentAmount + (i.waterUnit * i.waterRate) + (i.electricUnit * i.electricRate) AS total, EXISTS(SELECT 1 FROM Payment p WHERE p.invoiceId = i.invoiceId AND p.status = 'รอตรวจสอบ') AS pendingPayment FROM Invoice i JOIN Contract c ON c.contractId = i.contractId JOIN Room r ON r.roomId = c.roomId WHERE c.userId = ? ORDER BY i.dueDate DESC");
    $statement->execute([$user['userId']]);
    $tenantInvoices = $statement->fetchAll();
    $statement = db()->prepare("SELECT f.*, r.roomNumber, EXISTS(SELECT 1 FROM Payment p WHERE p.fineId = f.fineId AND p.status = 'รอตรวจสอบ') AS pendingPayment FROM Fine f JOIN Contract c ON c.contractId = f.contractId JOIN Room r ON r.roomId = c.roomId WHERE c.userId = ? ORDER BY f.fineDate DESC");
    $statement->execute([$user['userId']]);
    $tenantFines = $statement->fetchAll();
    $statement = db()->prepare("SELECT i.invoiceId, i.billMonth, r.roomNumber, i.rentAmount + (i.waterUnit * i.waterRate) + (i.electricUnit * i.electricRate) AS amount FROM Invoice i JOIN Contract c ON c.contractId = i.contractId JOIN Room r ON r.roomId = c.roomId WHERE c.userId = ? AND i.status = 'รอชำระ' AND NOT EXISTS(SELECT 1 FROM Payment p WHERE p.invoiceId = i.invoiceId AND p.status = 'รอตรวจสอบ') ORDER BY i.dueDate");
    $statement->execute([$user['userId']]);
    $unpaidInvoices = $statement->fetchAll();
    $statement = db()->prepare("SELECT f.fineId, f.description, r.roomNumber, f.amount FROM Fine f JOIN Contract c ON c.contractId = f.contractId JOIN Room r ON r.roomId = c.roomId WHERE c.userId = ? AND f.status = 'รอชำระ' AND NOT EXISTS(SELECT 1 FROM Payment p WHERE p.fineId = f.fineId AND p.status = 'รอตรวจสอบ') ORDER BY f.fineDate");
    $statement->execute([$user['userId']]);
    $unpaidFines = $statement->fetchAll();
}
?>
<section class="page-heading"><div><p class="eyebrow">PAYMENT RECORDS</p><h1>ใบแจ้งหนี้และการชำระเงิน</h1><p class="muted"><?= $user['role'] === 'Admin' ? 'สร้างใบแจ้งหนี้ บันทึกค่าปรับ และตรวจสอบการชำระเงิน' : 'ตรวจสอบใบแจ้งหนี้ ค่าปรับ และประวัติการชำระเงิน' ?></p></div></section>
<?php if ($user['role'] === 'Admin'): ?>
  <section class="panel form-panel"><div class="panel-heading"><div><p class="eyebrow">MONTHLY INVOICES</p><h2>สร้างใบแจ้งหนี้ประจำเดือน</h2></div></div><form method="post" action="index.php" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="generate_invoices"><input type="hidden" name="return_page" value="payments"><label>เดือน/รอบบิล<input name="billMonth" required maxlength="20" value="<?= e(date('m/Y')) ?>" placeholder="เช่น 10/2569"></label><label>วันครบกำหนด<input type="date" name="dueDate" required value="<?= e(date('Y-m-d', strtotime('+7 days'))) ?>"></label><button class="button primary" type="submit">สร้างใบแจ้งหนี้</button></form><p class="form-hint">ระบบสร้างหนึ่งใบต่อสัญญาที่ใช้งาน โดยต้องมีข้อมูลมิเตอร์ของเดือนเดียวกันก่อน และจะไม่สร้างซ้ำ</p></section>
  <section class="panel form-panel"><div class="panel-heading"><div><p class="eyebrow">TENANT FINES</p><h2>บันทึกค่าปรับ</h2></div></div><?php if ($activeContracts): ?><form method="post" action="index.php" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_fine"><input type="hidden" name="return_page" value="payments"><label>ผู้เช่า / ห้อง<select name="contractId" required><?php foreach ($activeContracts as $contract): ?><option value="<?= e($contract['contractId']) ?>">ห้อง <?= e($contract['roomNumber']) ?> · <?= e($contract['name']) ?></option><?php endforeach; ?></select></label><label>รายละเอียด<input name="description" maxlength="500" required></label><label>จำนวนเงิน<input type="number" name="amount" min="0.01" step="0.01" required></label><label>วันที่<input type="date" name="fineDate" value="<?= e(date('Y-m-d')) ?>" required></label><button class="button primary" type="submit">บันทึกค่าปรับ</button></form><?php else: ?><div class="empty-state compact"><strong>ไม่มีสัญญาเช่าที่กำลังใช้งาน</strong></div><?php endif; ?></section>
  <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">ISSUED INVOICES</p><h2>ใบแจ้งหนี้</h2></div><span class="panel-caption"><?= count($invoices) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>เดือน</th><th>ห้อง / ผู้เช่า</th><th>ครบกำหนด</th><th>ยอดรวม</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($invoices as $invoice): ?><tr><td><?= e($invoice['billMonth']) ?></td><td><?= e($invoice['roomNumber']) ?> · <?= e($invoice['name']) ?></td><td><?= e(date('d/m/Y', strtotime($invoice['dueDate']))) ?></td><td><strong><?= money($invoice['total']) ?> ฿</strong></td><td><span class="status-pill <?= $invoice['status'] === 'ชำระแล้ว' ? 'available' : 'pending' ?>"><?= e($invoice['status']) ?></span></td></tr><?php endforeach; ?></tbody></table><?php if (!$invoices): ?><div class="empty-state compact"><strong>ยังไม่มีใบแจ้งหนี้</strong></div><?php endif; ?></div></section>
  <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">FINES</p><h2>รายการค่าปรับ</h2></div><span class="panel-caption"><?= count($fines) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>วันที่</th><th>ห้อง / ผู้เช่า</th><th>รายละเอียด</th><th>จำนวนเงิน</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($fines as $fine): ?><tr><td><?= e(date('d/m/Y', strtotime($fine['fineDate']))) ?></td><td><?= e($fine['roomNumber']) ?> · <?= e($fine['name']) ?></td><td><?= e($fine['description']) ?></td><td><?= money($fine['amount']) ?> ฿</td><td><span class="status-pill <?= $fine['status'] === 'ชำระแล้ว' ? 'available' : 'pending' ?>"><?= e($fine['status']) ?></span></td></tr><?php endforeach; ?></tbody></table><?php if (!$fines): ?><div class="empty-state compact"><strong>ยังไม่มีรายการค่าปรับ</strong></div><?php endif; ?></div></section>
<?php else: ?>
  <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">INVOICES</p><h2>ใบแจ้งหนี้ของฉัน</h2></div><span class="panel-caption"><?= count($tenantInvoices) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>เดือน</th><th>ห้อง</th><th>ครบกำหนด</th><th>ค่าเช่า</th><th>ค่าน้ำ / ค่าไฟ</th><th>รวม</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($tenantInvoices as $invoice): ?><tr><td><?= e($invoice['billMonth']) ?></td><td><?= e($invoice['roomNumber']) ?></td><td><?= e(date('d/m/Y', strtotime($invoice['dueDate']))) ?></td><td><?= money($invoice['rentAmount']) ?> ฿</td><td><?= money($invoice['waterUnit'] * $invoice['waterRate'] + $invoice['electricUnit'] * $invoice['electricRate']) ?> ฿</td><td><strong><?= money($invoice['total']) ?> ฿</strong></td><td><span class="status-pill <?= $invoice['status'] === 'ชำระแล้ว' ? 'available' : 'pending' ?>"><?= e($invoice['status'] === 'รอชำระ' && $invoice['pendingPayment'] ? 'รอตรวจสอบ' : $invoice['status']) ?></span></td></tr><?php endforeach; ?></tbody></table><?php if (!$tenantInvoices): ?><div class="empty-state compact"><strong>ยังไม่มีใบแจ้งหนี้ที่ออกให้</strong></div><?php endif; ?></div></section>
  <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">FINES</p><h2>ค่าปรับ</h2></div><span class="panel-caption"><?= count($tenantFines) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>วันที่</th><th>ห้อง</th><th>รายละเอียด</th><th>จำนวนเงิน</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($tenantFines as $fine): ?><tr><td><?= e(date('d/m/Y', strtotime($fine['fineDate']))) ?></td><td><?= e($fine['roomNumber']) ?></td><td><?= e($fine['description']) ?></td><td><?= money($fine['amount']) ?> ฿</td><td><span class="status-pill <?= $fine['status'] === 'ชำระแล้ว' ? 'available' : 'pending' ?>"><?= e($fine['status'] === 'รอชำระ' && $fine['pendingPayment'] ? 'รอตรวจสอบ' : $fine['status']) ?></span></td></tr><?php endforeach; ?></tbody></table><?php if (!$tenantFines): ?><div class="empty-state compact"><strong>ไม่มีรายการค่าปรับ</strong></div><?php endif; ?></div></section>
  <section class="panel form-panel"><div class="panel-heading"><div><p class="eyebrow">SUBMIT PAYMENT</p><h2>แจ้งชำระเงิน</h2></div></div><?php if ($unpaidInvoices || $unpaidFines): ?><form method="post" action="index.php" enctype="multipart/form-data" class="inline-form payment-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="submit_payment"><input type="hidden" name="return_page" value="payments"><label>รายการที่ต้องการชำระ<select name="billingItem" required><option value="">เลือกรายการ</option><?php if ($unpaidInvoices): ?><optgroup label="ใบแจ้งหนี้"><?php foreach ($unpaidInvoices as $invoice): ?><option value="invoice:<?= e($invoice['invoiceId']) ?>">เดือน <?= e($invoice['billMonth']) ?> · ห้อง <?= e($invoice['roomNumber']) ?> · <?= money($invoice['amount']) ?> ฿</option><?php endforeach; ?></optgroup><?php endif; ?><?php if ($unpaidFines): ?><optgroup label="ค่าปรับ"><?php foreach ($unpaidFines as $fine): ?><option value="fine:<?= e($fine['fineId']) ?>"><?= e($fine['description']) ?> · ห้อง <?= e($fine['roomNumber']) ?> · <?= money($fine['amount']) ?> ฿</option><?php endforeach; ?></optgroup><?php endif; ?></select></label><label>วันที่ชำระ<input type="date" name="paymentDate" value="<?= e(date('Y-m-d')) ?>" required></label><label>แนบหลักฐาน<input type="file" name="evidence" accept="image/jpeg,image/png,image/webp" required></label><button class="button primary" type="submit">ส่งหลักฐาน</button></form><?php else: ?><div class="empty-state compact"><strong>ไม่มีรายการค้างชำระ</strong><small>เมื่อมีใบแจ้งหนี้หรือค่าปรับ จะแสดงให้เลือกชำระที่นี่</small></div><?php endif; ?></section>
<?php endif; ?>
<section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">HISTORY</p><h2>ประวัติการชำระเงิน</h2></div><span class="panel-caption"><?= count($payments) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><?php if ($user['role'] === 'Admin'): ?><th>ผู้เช่า</th><?php endif; ?><th>ห้อง</th><th>รายการ</th><th>วันที่</th><th>ยอดชำระ</th><th>หลักฐาน / ใบเสร็จ</th><th>สถานะ</th><?php if ($user['role'] === 'Admin'): ?><th>ดำเนินการ</th><?php endif; ?></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><?php if ($user['role'] === 'Admin'): ?><td><?= e($payment['name']) ?></td><?php endif; ?><td><?= e($payment['roomNumber']) ?></td><td><?php if (!empty($payment['billMonth'])): ?>ใบแจ้งหนี้ <?= e($payment['billMonth']) ?><?php elseif (!empty($payment['fineDescription'])): ?>ค่าปรับ: <?= e($payment['fineDescription']) ?><?php else: ?>รายการเดิม<?php endif; ?></td><td><?= e(date('d/m/Y', strtotime($payment['paymentDate']))) ?></td><td><strong><?= money($payment['amount']) ?> ฿</strong></td><td><?php if ($payment['evidence']): ?><a class="text-link" href="file.php?id=<?= e($payment['paymentId']) ?>" data-image-preview data-image-alt="หลักฐานการชำระเงิน">ดูสลิป</a><?php endif; ?><?php if ($payment['status'] === 'อนุมัติ'): ?> <a class="text-link" href="receipt.php?id=<?= e($payment['paymentId']) ?>">ดูใบเสร็จ</a><?php endif; ?><?php if (!$payment['evidence'] && $payment['status'] !== 'อนุมัติ'): ?>—<?php endif; ?></td><td><span class="status-pill <?= $payment['status'] === 'อนุมัติ' ? 'available' : ($payment['status'] === 'ปฏิเสธ' ? 'rejected' : 'pending') ?>"><?= e($payment['status']) ?></span></td><?php if ($user['role'] === 'Admin'): ?><td><?php if ($payment['status'] === 'รอตรวจสอบ'): ?><form method="post" action="index.php" class="row-actions"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="paymentId" value="<?= e($payment['paymentId']) ?>"><input type="hidden" name="return_page" value="payments"><button class="button tiny success" name="action" value="review_payment" data-confirm="อนุมัติหลักฐานนี้หรือไม่?">อนุมัติ</button><button class="button tiny danger" name="action" value="reject_payment">ปฏิเสธ</button></form><?php else: ?>—<?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php if (!$payments): ?><div class="empty-state"><span>฿</span><strong>ยังไม่มีประวัติการชำระ</strong><small>รายการชำระเงินจะแสดงที่นี่</small></div><?php endif; ?></div></section>
